    "explanation": "Tıbbi Deontoloji Nizamnamesi'ne (Madde 18) göre **acil yardım zorunluluğu ile resmi veya insani görevin getirdiği mecburiyet halleri hariç olmak üzere**, hekim mesleki veya kişisel gerekçelerle bir hastanın tedavisini üstlenmeyi reddedebilir; ancak hastanın zarar görmemesi için durumu zamanında bildirmekle yükümlüdür (B doğru). Hekim zorla veya sınırsız bir tedavi yükümlülüğü altında değildir; acil ve resmi görev dışındaki durumlarda mesleki/kişisel nedenlerle hastayı kabul etmeme hakkı mevzuatta açıkça tanınmıştır (A yanlış). Hastayı kabul etmeme hakkının kullanılabilmesi için mahkeme kararına gerek yoktur, bu karar hekimin kendi mesleki özerkliği çerçevesinde alınır (C yanlış). Acil durumlarda hayati tehlike altındaki hastaya tıbbi yardım sunmak yasal ve etik bir zorunluluktur; acil hastanın bakılmadan geri çevrilmesi hekimlik ödeviyle bağdaşmaz (D yanlış). Hastanın maddi durumunun yetersizliği hiçbir zaman ret gerekçesi yapılamaz; tıbbi etik ilkeleri gereği ekonomik ayrımcılık yasaktır ve ret yalnızca acil olmayan hallerde meşru mesleki veya kişisel nedenlerle mümkündür (E yanlış).",
