    "explanation": "Henüz hastalık ortaya çıkmadan risk faktörlerini kontrol altına alarak sağlıklı durumu korumayı hedefleyen **düzenli fiziksel egzersiz ve dengeli beslenme ile sağlıklı beden kitle indeksinin sürdürülmesi**, halk sağlığında birincil (primer) koruma örneğidir (D doğru). İnme geçirmiş bir hastaya sekel ve işlev kaybını azaltmak amacıyla fizik tedavi ve rehabilitasyon uygulanması hastalığın geç dönem sonuçlarını sınırlayan üçüncül (tersiyer) korumadır (A yanlış). Tanı almış diyabetik hastada kan şekeri kontrolü ile retinopati gibi organ komplikasyonlarının önlenmesi, hastalığın ilerleyip sakatlığa yol açmasını önlemeye yönelik üçüncül (tersiyer) koruma kapsamındadır (B yanlış). Asemptomatik bireylerde mamografi ile erken evre meme kanseri taranması, hastalığı erken yakalayıp tedavi etmeyi amaçlayan ikincil (sekonder) korumadır (C yanlış). Miyokard enfarktüsü sonrası koroner anjiyografi yapılması gelişmiş akut koroner olayın tanısal ve girişimsel tedavisine yönelik ikincil/üçüncül klinik müdahaledir, primer koruma değildir (E yanlış).",
