    "professor": "Belirtilmemiş",
    "question": "Bilinç düzeyini değerlendirmede kullanılan Glasgow Koma Skalası'nda (GKS) değerlendirilen parametreler ve bir hastanın alabileceği en düşük toplam puan aşağıdakilerden hangisinde doğru verilmiştir?",
    "options": [
      {
        "letter": "A",
        "text": "Göz açma, Sözel yanıt, Motor yanıt — En düşük puan: 3"
      },
      {
        "letter": "B",
        "text": "Pupil refleksi, Bilinç, Ağrıya yanıt — En düşük puan: 1"
      },
      {
        "letter": "C",
        "text": "Sözel yanıt, Ağrı yanıtı, Kas tonusu — En düşük puan: 4"
      },
      {
        "letter": "D",
        "text": "Göz açma, Motor yanıt, Refleksler — En düşük puan: 5"
      },
      {
        "letter": "E",
        "text": "Solunum, Nabız, Tansiyon — En düşük puan: 0"
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Glasgow Koma Skalası'nda (GKS) göz açma (1–4), sözel yanıt (1–5) ve motor yanıt (1–6) olmak üzere üç parametre değerlendirilir; hiçbir yanıta 0 puan verilmediğinden alınabilecek en düşük toplam skor **3**tür.",
    "note": "Hatırlanan 3 şıklı sorudan 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
