    "explanation": "Tiyol bileşikleri serbest sülfhidril (-SH) grupları aracılığıyla ağır metallerle çok kuvvetli ve stabil şelat kompleksleri oluşturur; bu nedenle dimerkaprol (BAL) gibi maddeler toksikolojide **ağır metal (arsenik, cıva, kurşun) zehirlenmelerinde şelatör (panzehir)** olarak kullanılır.",
