    "explanation": "Kimyadaki 'benzer benzeri çözer' ilkesine göre polar çözücüler polar ve iyonik bileşikleri, apolar çözücüler ise apolar bileşikleri çözer; polar su molekülleri iyonik kristal **NaCl tuzunu** iyon-dipol etkileşimleriyle hidratize ederek çok iyi çözerken, hidrofobik apolar lipidler su molekülleriyle etkileşemediğinden suda çözünmez (C doğru). Su molekülü, oksijen atomunun yüksek elektronegatifliği ve açısal (bükülmüş) moleküler geometrisi nedeniyle kalıcı dipol momente sahip güçlü bir **polar** çözücüdür, apolar değildir (A yanlış). Suda kolay çözünen maddeler lipofilik (yağ seven) değil, suyla hidrojen bağı veya elektrostatik etkileşim kurabilen **hidrofilik** (polar/iyonik) moleküllerdir (B yanlış). Apolar hidrokarbonlar polar su molekülleriyle karışamaz, hidrofobik etki nedeniyle bir araya toplanarak homojen çözelti yerine heterojen faz ayrımı oluşturur (D yanlış). Sofra tuzu (NaCl) Na⁺ ve Cl⁻ iyonlarından oluşan iyonik bir bileşik olduğundan polar su molekülleri tarafından kolayca çözünür (E yanlış).",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
