    "explanation": "Sağlık sisteminin verimli işlemesi için **halkın sağlık sorunlarında doğrudan hastanelere değil, ilk olarak birinci basamak birimlerine (Aile Hekimliği/ASM) başvurması esastır**; halkın ilk başvuru birimlerine gerek olmadığı yönündeki yaklaşım sevk zincirini ve basamaklandırma mantığını yıkar.",
    "note": "",
    "q_type": "mcq",
