    "subject": "Halk Sağlığı",
    "professor": "Ufuk Berberoğlu",
    "question": "Küresel tütün kullanımını tersine çevırdğı Kanıtlanmış olan yöntemler (MPOWER) konusunda hangısı ?",
    "options": [
      {
        "letter": "A",
        "text": "Ülkemız, tüm yöntem alanlarında gerekleri yenne getirememş durumdadır."
      },
      {
        "letter": "B",
        "text": "Tüm toplumu sigara dumam maruziyetinin zararlarından korumak"
      },
      {
        "letter": "C",
        "text": "Tütün kullanımının bırakılmasına uygun yardımı onerrnek ve sağlamak"
      },
      {
        "letter": "D",
        "text": "Tütün reklam. promosyon ve sponsorluktan yasaklama uygulamalarım desteklemek"
      },
      {
        "letter": "E",
        "text": "Tütün kullanımına başlatmamayÛ sağlayan çalışmaları geliştirmek"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "DSÖ'nün tütün kontrolünde küresel etkinliği kanıtlanmış altı bileşenli **MPOWER** paketinde yer alan başlıklar izleme (M), dumandan koruma (P), bırakmaya yardım (O), tehlikeler konusunda uyarma (W), reklam/sponsorluk yasakları (E) ve vergileri artırma (R) olup, 'tütün kullanımına başlatmamayı sağlayan çalışmalar' doğrudan bu altı MPOWER harfi arasında tanımlanmış ayrı bir bileşen değildir ve soru anahtarında E seçeneği işaretlenmiştir (E yanlış). Türkiye MPOWER kriterlerinin tümünü en üst düzeyde uygulayarak DSÖ tarafından küresel tütün kontrolünde örnek ülke gösterildiğinden ülkemizin tüm yöntem alanlarında gerekleri yerine getiremediği iddiası da gerçeği yansıtmamaktadır (A yanlış). Tüm toplumu sigara dumanı maruziyetinin zararlarından korumak MPOWER paketindeki P (Protect people from tobacco smoke) bileşenidir (B doğru). Tütün kullanımının bırakılmasına uygun yardımı önermek ve sağlamak MPOWER paketindeki O (Offer help to quit tobacco use) bileşenidir (C doğru). Tütün reklam, promosyon ve sponsorluklarını yasaklama uygulamalarını desteklemek MPOWER paketindeki E (Enforce bans on tobacco advertising, promotion and sponsorship) bileşenidir (D doğru).",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": "",
