    "professor": "Abdurrahman Yılmaz",
    "question": "ELDİVEN KULLANIMI İLE İLGİLİ OLARAK HANGİ İFADE YANLIŞTIR?",
    "options": [
      {
        "letter": "A",
        "text": "Temas veya sıkı temas izolasyonundaki odasına girmeden önce eldiven hasta kullanılmalıdır,"
      },
      {
        "letter": "B",
        "text": "Eldivenler yıkanıp tekrar kullanılabilen malzemeden yapılmışlardır."
      },
      {
        "letter": "C",
        "text": "Bir başka hastaya aynı eldiven ile temas edilmemelidir."
      },
      {
        "letter": "D",
        "text": "Eldivenler, önlük giyildiği durumlarda önlüğün kol manşetleri üzerine çekilmelidir."
      },
      {
        "letter": "E",
        "text": "Bütünlüğü bozulmuş cilt ile veya mukoza ile temas durumunda eldiven kullanılmalıdır"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Tıbbi amaçlı kullanılan muayene ve cerrahi eldivenler tek kullanımlık bariyer ekipmanlarıdır; yıkanmaları veya dezenfektanla temizlenmeleri durumunda materyal yapılarındaki mikro gözenekler bozularak patojen geçirgenliği artar ve yırtılma riski doğar, dolayısıyla **eldivenler asla yıkanıp tekrar kullanılmaz** (B yanlış). Temas veya sıkı temas izolasyonu uygulanan hasta odasına girmeden önce enfeksiyon bulaşını önlemek için eldiven giyilmelidir (A doğru). Çapraz bulaşmayı engellemek amacıyla bir hastaya temas ettikten sonra eldiven çıkarılıp el hijyeni sağlanmalı, aynı eldivenle başka bir hastaya kesinlikle temas edilmemelidir (C doğru). Önlük giyilen durumlarda bilek bölgesinde açık deri alanı kalmaması için eldiven manşetleri önlüğün kol manşetlerinin üzerine çekilmelidir (D doğru). Bütünlüğü bozulmuş deri, kan, vücut sıvıları veya mukoza ile temas olasılığında mutlaka eldiven kullanılmalıdır (E doğru).",
