    "open_answer": "",
    "explanation": "Hastanelerde düşme riskini önlemek için çevre düzenlemesi, aydınlatma, kaygan zeminlerin engellenmesi ve refakatçi eğitimi uygulanır; **düşme riski olan tüm hastalara istisnasız sedatif ilaç verilmesi veya kısıtlama uygulanması** deliriumu tetikleyip riski daha da artıran kabul edilemez bir uygulamadır.",
