    "explanation": "Asit-baz titrasyonunda indikatörler kendileri zayıf organik asit veya bazlardır; bu nedenle ortama fazla miktarda indikatör eklenmesi ortamın pH dengesini bozar ve dönüm noktasını saptırır; **indikatör hacminin önemsiz olduğu ve istenildiği kadar eklenebileceği ifadesi yanlıştır**, yalnızca birkaç damla damlatılmalıdır.",
