    "question": "Aşağıdakilerden hangisi Batıda \"Avicenna- adı ile tanınan ve tabipler sultanı lakaplı Ebu Ali İbn Sina'nın (980—1037) tıp alanında yaptığı hizmetlerden biridir?",
