    "explanation": "Bilinçsiz bir erişkinde veya resüsitasyon sırasında nabız kontrolünde ilk ve en güvenilir şekilde palpe edilen, hipotansiyonda bile en son kaybolan santral damar boyundaki **Arteria carotis communis**tir.",
