    "professor": "Abdurrahman Yılmaz",
    "question": "Aşağıdakilerden hangisi yaşam zincirinin öğelerinden değildir.",
    "options": [
      {
        "letter": "A",
        "text": "Kalp durmasının erken tanınması ve acil sağlık hizmetlerinin (112/mavi kod) erken aktivasyonu"
      },
      {
        "letter": "B",
        "text": "Erken kalp masajı"
      },
      {
        "letter": "C",
        "text": "Erken defibrilasyon"
      },
      {
        "letter": "D",
        "text": "Etkili Erişkin İleri Yaşam Desteğinin başlanması"
      },
      {
        "letter": "E",
        "text": "Hava yolunun açıklığını sağlamak"
      }
    ],
