    "professor": "Soycan Mızrak",
    "question": "Amonyağın hidrojenleri yerine alkil gruplarının bağlanması ile kuarterner amonyum katyonu (R4N+) meydana gelir. Aşağıdakilerden hangisi hücre membran yapısında bulunan bir kuarterner amonyum bileşiğidir?",
