    "professor": "Ayşe Özdemir",
    "question": "Amfolitler, amfolitin izoelektrik noktası denen bir pH ortamında, eşit sayıda negatif  ve pozitif (+) yük  içerirler. Aşağıdaki ifadelerden hangisi doğru olarak verilmiştir?",
