    "explanation": "Amfoterik moleküller olan aminoasitlerin izoelektrik noktasından (pI) daha düşük pH ortamında (kuvvetli asidik ortam) serbest hidrojen iyonları amino gruplarını protonlar (-NH3+); bu nedenle aminoasitler pI'dan düşük pH'da net **pozitif yüklü katyon** halinde bulunurlar.",
