    "subject": "Anatomi",
    "professor": "Mehmet Karayaman",
    "question": "Hasta karşısında, hekimin sorumluluğu söz konusu olduğunda, ilk değerlendirilecek nokta hekimin davranışının meslek ahlakına ve hekimin vicdanına uygun olup olmadığıdır. Tıp bilimine uygun olmayan uygulamalar, sorumluluğu gerektirir. Hekimler, aşağıdaki durumlardan hangisinden sorumlu tutulamaz?",
