    "question": "Osmanlı’nın aşıcı kadınları, çiçek geçiren çocukların irinlerinden aldıkları aşıyı, çiçek geçirmemiş çocukların kol ya da bacaklarını çizerek üzerine koyuyor ve bir ceviz kabuğuyla kapatıyorlardı. Bu yöntemle aşılanan çocuklar çiçek hastalığını çoğunlukla daha hafif atlatıyorlardı. Bu usulü Avrupa’ya yazdığı mektuplarda anlatarak aşının oralarda da uygulanmasını sağlayan kişi aşağıdakilerden hangisidir?",
