    "professor": "Abdurrahman Yılmaz",
    "question": "AşAĞIDAKİLERDEN HANGİSİ HASTANEDE DÜşME KAYNAKLI RİSKLERİ AZALTMAK İÇİN YAPILMASI GEREKEN FAALİYETLERDEN BİRİSİ DEĞİLDİR?",
