    "explanation": "Tıbbi muayene ve işlem eldivenleri tek kullanımlık (disposable) koruyucu bariyerlerdir; yıkandığında veya dezenfektanla silindiğinde yapılarındaki mikro gözenekler genişleyerek geçirgenlik artar, bu nedenle **eldivenler yıkanıp tekrar kullanılamaz** (B yanlış). Temas veya sıkı temas izolasyonundaki hastanın odasına girmeden önce eldiven giyilmesi standart enfeksiyon kontrol önlemidir (A doğru). Hastalar arası mikroorganizma taşınmasını önlemek için aynı eldivenle başka bir hastaya kesinlikle temas edilmemelidir (C doğru). Koruyucu önlük kullanıldığında bilek cildinin açıkta kalmasını önlemek amacıyla eldivenler önlüğün kol manşetlerinin üzerine çekilmelidir (D doğru). Bütünlüğü bozulmuş cilt veya mukoza ile temas öncesinde kan ve vücut sıvısı bulaşını engellemek için eldiven giyilmelidir (E doğru).",
