    "question": "Toplum Sağlığı Merkezinin görevlerine ilişkin olarak hangisi doğrudur ?",
    "options": [
      {
        "letter": "A",
        "text": "Çevre sağlığı hizmetleri"
      },
      {
        "letter": "B",
        "text": "Gaitada gizli kan testi"
      },
      {
        "letter": "C",
        "text": "Bakanlıkça belirlenen ve uygulamaya konulan kişiye yönelik sağlık programlarını yürütmek- Öğrencinin işaretlediği"
      },
      {
        "letter": "D",
        "text": "Gebe ve bebek izlemleri"
      },
      {
        "letter": "E",
        "text": "Ev ziyaretleri yaparak sağlık durum tespiti yapmak."
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Toplum Sağlığı Merkezleri (TSM); bireysel poliklinik ve takip hizmetleri sunan aile hekimliklerinden farklı olarak, bölgedeki su güvenliği, gıda ve çevre denetimleri, vektör kontrolü ve filyasyon gibi **topluma yönelik çevre sağlığı hizmetlerini** yürütmek ve koordine etmekle görevlidir (A doğru). Gaitada gizli kan testi kolorektal kanser taramasında kullanılan kişiye yönelik bir tarama işlemi olup aile sağlığı merkezleri veya KETEM tarafından birey bazında uygulanır (B yanlış). Bakanlıkça belirlenen **kişiye yönelik** sağlık programlarını uygulamak bireysel hizmet sunan aile hekimliği birimlerinin görevidir; TSM topluma yönelik sağlık programlarını yönetir (C yanlış). Gebe ve bebek izlemleri kayıtlı nüfusa yönelik bireysel koruyucu hizmet olarak aile hekimliği birimlerinin sorumluluğundadır (D yanlış). Ev ziyaretleri yaparak bireysel sağlık durum tespiti yapmak TSM'nin değil kayıtlı hastalarından sorumlu aile hekimlerinin görevidir (E yanlış).",
