    "question": "Aşağıdaki önermelerin doğru (D) ve yanlış (Y) sıralaması hangi seçenektedir?Sağlığın tanımında yer alan bedensel / ruhsal / toplumsal yönlerdenTAM İYİLİK DURUMU ögeleri içinde en önemlisi “toplumsal” yönden iyiliktir.Toplumsal yapı ile sağlık arasındaki ilişki, daha çok ilkinin 2. sini belirlemesi  yönündedir.Genetik yapı ya da biyolojik yapı, sosyal insanın oluşumunda ancak % 40 dolayında pay sahibidir.Sağlık ile sosyo-ekonomik koşullar arasındaki ilişki, tıp bilimlerinin gelişmesiyle zayıflamıştır.Olumsuz sosyal çevrenin kendisi, doğrudan hastalık oluşturabilir.",
