    "subject": "Tıp Eğitimi ve Becerileri",
    "professor": "Yücel Gültekin",
    "question": "Delici karın yaralanmalarında ilkyardım için hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Öncelikle yaralının bilinç kontrolü yapılır."
      },
      {
        "letter": "B",
        "text": "Ağızdan yiyecek ya da içecek bir şey verilmez."
      },
      {
        "letter": "C",
        "text": "Dışarı çıkan organlar içeri sokulmaya çalışılmaz ."
      },
      {
        "letter": "D",
        "text": "Yaralıya koma pozisyonu verilir."
      },
      {
        "letter": "E",
        "text": "Yaralanmanın üzerine geniş ve nemli temiz bir bez örtülür."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Delici karın yaralanmalarında karın içi basıncı azaltmak ve kasları gevşetmek için kazazede sırtüstü yatırılır ve dizleri bükülür (yara transvers ise bacaklar bükülür, longitudinal ise düz tutulur); **yaralıya koma pozisyonu verilmesi** karın içi organlara bası yapacağı ve kanamayı artıracağı için kesinlikle yanlıştır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
