    "subject": "Anatomi",
    "professor": "Mahmut Çay",
    "question": "En fazla spinal sinir çıkışı aşağıdaki bölgelerden hangisinde bulunur?",
    "options": [
      {
        "letter": "A",
        "text": "Servikal"
      },
      {
        "letter": "B",
        "text": "Torakal"
      },
      {
        "letter": "C",
        "text": "Lumbal"
      },
      {
        "letter": "D",
        "text": "Sakral"
      },
      {
        "letter": "E",
        "text": "Koksigeal"
      }
    ],
    "answer": "B",
    "open_answer": "",
    "explanation": "Medulla spinalis boyunca 8 servikal, 12 torakal, 5 lumbal, 5 sakral ve 1 koksigeal olmak üzere toplam 31 çift spinal sinir çıkar; dolayısıyla sayıca en fazla spinal sinir kökünün çıktığı bölge **12 çift ile Torakal bölge**dir.",
    "note": "",
