    "open_answer": "",
    "explanation": "Kafatasındaki suturalar oynamaz (sinartroz) eklemlerdir; columna vertebralis'te omur gövdeleri arasındaki symphysis intervertebralis eklemleri ise discus intervertebralis aracılığıyla sınırlı hareket kabiliyetine sahip **az oynar (amfiartroz) eklemlerdir**, oynamaz eklem olduğu ifadesi yanlıştır.",
    "note": "",
