    "explanation": "Bir neden-sonuç kurgusunda sonuca yol açtığı varsayılan ve manipüle edilen/incelenen faktör bağımsız değişkendir; burada otizm bağımlı değişken, **oral kontraseptif ilaç** bağımsız değişkendir.",
