    "q_num": 40,
    "subject": "Anatomi",
    "professor": "Senem Şanlı",
    "question": "Uşak ilinde 2016 yılında Hepatit B pozitif vaka sayısı 350 iken, 2017 yılında Hepatit B pozitif vaka sayısı 150 olmuştur. Bir yıldaki Hepatit B değişim oranını hesaplayınız.",
    "options": [
      {
        "letter": "A",
        "text": "- %33,3"
      },
      {
        "letter": "B",
        "text": "%40"
      },
      {
        "letter": "C",
        "text": "- %42,8"
      },
      {
        "letter": "D",
        "text": "-%57,1"
      },
      {
        "letter": "E",
        "text": "%46,7"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Değişim oranı = [(Son Değer - İlk Değer) / İlk Değer] × 100 = [(150 - 350) / 350] × 100 = -200 / 350 × 100 = **-%57,1** olarak hesaplanır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
