    "question": "Bir şirkette birlikte çalışan 20-25 yaş aralığında 4 arkadaşın kan şekeri ölçümü sonuçları 83, 88, 90 ve 85 olarak bulunmuştur. Verilerin varyasyon katsayısı nedir?",
