    "explanation": "Varyasyon katsayısı formülü CV = (Standart Sapma / Ortalama) × 100 şeklindedir; (3,11 / 86,5) × 100 işlemi uygulandığında varyasyon katsayısı **%3,59** olarak elde edilir.",
