    "question": "Kızamık tedavisinde kullanılacak yeni bir aşı türünn geliştirilmesi sonucu yapılan araştırmalar neticesinde elde edilen 48 farklı aşı örneğinin 32 tanesinin beklenen etkiyi sergilediği (başarılı), 16 tanesinin ise beklenen etkiyi sergilemede yetersiz olduğu (başarısız) gözlenmiştir. Bu durumun 3:1 oranına uygun olup-olmadığını belirleyiniz. Fc = 3,841",
