    "q_num": 64,
    "subject": "Biyokimya",
    "professor": "Ayşe Özdemir",
    "question": "Aşağıdakilerden hangisinde geçici dipoller oluşur?",
    "options": [
      {
        "letter": "A",
        "text": "Hbr"
      },
      {
        "letter": "B",
        "text": "HCl"
      },
      {
        "letter": "C",
        "text": "NH3"
      },
      {
        "letter": "D",
        "text": "H2O"
      },
      {
        "letter": "E",
        "text": "N2"
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Apolar ve simetrik bir diatomik molekül olan **Azot gazı (N2)** kalıcı elektriksel dipole sahip değildir; elektron bulutunun anlık dalgalanmaları sonucu yalnızca geçici indüklenmiş dipoller (London dağılım kuvvetleri) oluşturur. H2O, NH3 ve HCl ise kalıcı polar dipollere sahiptir.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
