    "professor": "Belirtilmemiş",
    "question": "Sosyal tıbbın öncüsü Rudolf Virchow'un sağlık ve toplum ilişkisi konusundaki görüşleri için aşağıdakilerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Tıp bir sosyal bilimdir ve politika geniş ölçekli tıptan başka bir şey değildir."
      },
      {
        "letter": "B",
        "text": "Hekimlerin görevi hastaları tedavi etmenin yanı sıra toplumsal eşitsizliklere dikkat çekmektir."
      },
      {
        "letter": "C",
        "text": "Halk sağlığı sorunları yalnızca bireylerin kendi kişisel sorumluluğundadır, devlet müdahalesi gerekmez."
      },
      {
        "letter": "D",
        "text": "Sağlık sorunları sadece biyomedikal müdahalelerle değil, toplumsal reformlarla çözülebilir."
      },
      {
        "letter": "E",
        "text": "Hastalıkların ortaya çıkışında ve yayılmasında sosyoekonomik faktörler kritik role sahiptir."
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Sosyal tıbbın kurucusu Rudolf Virchow'a göre tıp bir sosyal bilimdir ve hekimler yoksulluk ile adaletsizliğin doğal avukatlarıdır; bu nedenle **halk sağlığı sorunlarının yalnızca bireylerin kişisel sorumluluğu olduğu ve devlet müdahalesi gerekmediği savı** Virchow'un toplum hekimliği felsefesine tamamen aykırıdır.",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": "",
    "ai_completion": "options"
