    "professor": "Belirtilmemiş",
    "question": "'Toplumdan çok bireyler kendi sağlıklarından tek başına sorumludurlar' şeklindeki katı liberal sağlık yaklaşımının halk sağlığı açısından temel sakıncası nedir?",
