    "explanation": "DSÖ'nün MPOWER paketinde yer alan **'O' (Offer help to quit tobacco use)** bileşeni, tütün kullanımını bırakmak isteyen bireylere **sigara bırakma poliklinikleri ve ALO 171 gibi danışma hatları üzerinden profesyonel tıbbi ve davranışsal destek sağlanmasını** ifade eder (A doğru). Hafif (light) sigara dağıtmak tütün bağımlılığını sürdürür ve zarar azaltımı sağlamadığı kanıtlandığından kontrol stratejisi değildir (B yanlış). Elektronik sigaralar da nikotin bağımlılığını devam ettirip solunum yolu toksisitesine yol açtığından kanıta dayalı bırakma tedavisi olarak önerilmez (C yanlış). Bırakma tedavilerini sosyal güvenlik kapsamından çıkarmak hastaların tedaviye finansal erişimini engelleyerek bırakma oranlarını düşürür (D yanlış). Tütün bağımlılığı tedavi edilmesi gereken kronik bir bağımlılık olduğundan kullanıcıları cezalandırmak MPOWER'ın destekleyici sağlık hizmeti yaklaşımıyla bağdaşmaz (E yanlış).",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
