    "professor": "Belirtilmemiş",
    "question": "Bir toplumda sağlık hizmetlerinin ve yaşam standartlarının iyileşmesi sonucunda doğuşta beklenen yaşam süresi ile ilgili aşağıdaki ifadelerden hangisi doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Doğuşta beklenen yaşam süresi bebek ölümlerinden bağımsızdır."
      },
      {
        "letter": "B",
        "text": "Erkeklerde doğuşta beklenen yaşam süresi kadınlardan belirgin olarak daha uzundur."
      },
      {
        "letter": "C",
        "text": "Gelişmiş ülkelerde doğuşta beklenen yaşam süresi gelişmekte olan ülkelerden daha düşüktür."
      },
      {
        "letter": "D",
        "text": "Doğuşta beklenen yaşam süresi bir mortalite göstergesi değildir."
      },
      {
        "letter": "E",
        "text": "Ülkemizde ve dünyada son 10 yıllarda sağlık hizmetlerinin gelişmesiyle doğuşta beklenen yaşam süresi artmıştır."
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Doğuşta beklenen yaşam süresi, bir toplumda mevcut yaşa özel ölüm hızlarının sürmesi halinde yeni doğan bir bebeğin ortalama kaç yıl yaşayacağını gösteren temel sağlık ölçütüdür; son on yıllarda aşılama, temiz su, beslenme ve klinik tıptaki ilerlemeler sayesinde hem Türkiye'de hem dünyada **doğuşta beklenen yaşam süresi belirgin biçimde artmıştır** (E doğru). Doğuşta beklenen yaşam süresi bebek ölümlerinden bağımsız değildir; aksine yaşamın en başındaki (0-1 yaş) kayıplar yaşam süresinden en çok yıl eksilttiği için bebek ölümlerindeki azalma doğuşta beklenen yaşam süresini doğrudan yükseltir (A yanlış). Biyolojik ve davranışsal nedenlerle hemen her toplumda **kadınlarda** doğuşta beklenen yaşam süresi erkeklerden daha uzundur, erkeklerde daha uzun değildir (B yanlış). Yaşam standartları ve sağlık hizmetleri gelişmiş ülkelerde daha ileri düzeyde olduğundan, gelişmiş ülkelerde doğuşta beklenen yaşam süresi gelişmekte olan ülkelerden daha düşük değil daha yüksektir (C yanlış). Doğuşta beklenen yaşam süresi yaşam tablolarında tüm yaş gruplarının mortalite hızlarından türetildiği için en kapsamlı **mortalite (ölümlülük) göstergelerinden** biridir (D yanlış).",
    "note": "Hatırlanan çıkmış soru kökünden 5 şıklı çoktan seçmeli soruya tamamlanmıştır.",
