    "professor": "Belirtilmemiş",
    "question": "Türkiye'de son yıllarda anne sağlığı hizmetlerinin gelişimi ve TÜİK verilerine göre anne ölüm hızı (yüz binde) düzeyi ile ilgili hangisi doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Doğumların hastanede yapılması ve antenatal bakım ile anne ölüm hızı yüz binde 13-15 seviyelerine gerilemiştir."
      },
      {
        "letter": "B",
        "text": "Anne ölümlerinin en sık nedeni çocukluk çağı aşılarıdır."
      },
      {
        "letter": "C",
        "text": "Anne ölüm hızı Türkiye'de son 20 yılda artış göstermiştir."
      },
      {
        "letter": "D",
        "text": "Türkiye'de anne ölüm hızı yüz binde 100'ün üzerindedir."
      },
      {
        "letter": "E",
        "text": "Anne ölüm hızının hesaplanmasında payda tüm kadın nüfustur."
      }
    ],
    "answer": "A",
    "open_answer": "",
    "explanation": "Türkiye'de son yirmi yılda antenatal bakım kalitesinin yükselmesi, yüksek riskli gebeliklerin erken saptanması, acil obstetrik bakım ağının güçlenmesi ve doğumların %98'in üzerinde sağlık kuruluşlarında yaptırılması sayesinde **anne ölüm hızı yüz binde 13-15 seviyelerine gerilemiştir** (A doğru). Anne ölümlerinin en sık nedenleri çocukluk çağı aşıları değil; doğum sonu obstetrik kanamalar, gebeliğin hipertansif bozuklukları (preeklampsi/eklampsi), sepsis ve emboli gibi doğrudan veya dolaylı obstetrik komplikasyonlardır (B yanlış). Türkiye'de anne ölüm hızı son 20 yılda artış değil, yüz binde 60'ların üzerinden 13-15 bandına doğru dramatik bir **düşüş** göstermiştir (C yanlış). Yüz binde 100'ün üzerindeki anne ölüm hızları sağlık altyapısı yetersiz az gelişmiş bölgelere özgüdür; Türkiye'de bu oran yüz binde 15'in altındadır (D yanlış). Anne ölüm hızının (oranının) hesaplanmasında paydada tüm kadın nüfus değil, o dönemdeki toplam **canlı doğum sayısı** yer alır (E yanlış).",
