    "question": "Nüfus piramitleri ile ilgili aşağıdaki ifadelerden hangisi doğrudur?",
    "options": [
      {
        "letter": "A",
        "text": "Nüfus piramitlerinde kadınlar her zaman sol tarafta gösterilir."
      },
      {
        "letter": "B",
        "text": "Piramidin tavanı doğurganlık hızını yansıtır."
      },
      {
        "letter": "C",
        "text": "Nüfus piramidinden bağımlılık oranı hesaplanamaz."
      },
      {
        "letter": "D",
        "text": "Nüfus piramitleri toplumun yaş ve cinsiyet yapısını, geçmişteki doğum-ölüm trendlerini ve gelişmişlik düzeyini gösterir."
      },
      {
        "letter": "E",
        "text": "Gelişmiş ülkelerin nüfus piramitleri geniş tabanlı üçgen şeklindedir."
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "**Nüfus piramitleri** bir toplumun yaş gruplarına ve cinsiyete göre dağılımını görselleştiren grafikler olup geçmişteki doğum, ölüm, savaş ve göç dalgalarını, bağımlılık oranlarını ve toplumun demografik gelişmişlik düzeyini ortaya koyar (D doğru). Uluslararası demografi standardında nüfus piramitlerinin sol tarafında geleneksel olarak **erkekler**, sağ tarafında ise **kadınlar** gösterilir; kadınlar her zaman sol tarafta yer almaz (A yanlış). Piramidin **tabanı** (0-4 yaş grubu) doğurganlık hızını yansıtırken, piramidin **tavanı** (tepesi) ileri yaşlara ulaşabilen nüfusu ve mortalite düzeyini gösterir (B yanlış). Nüfus piramidinden 0-14 yaş (çocuk) ve 65 yaş üzeri (yaşlı) nüfus toplamının 15-64 yaş (üretken) nüfusa bölünmesiyle **yaş bağımlılık oranı** doğrudan hesaplanabilir (C yanlış). Geniş tabanlı ve hızla sivrilen üçgen şeklindeki nüfus piramitleri yüksek doğurganlık ve yüksek ölüm hızlarına sahip gelişmekte olan veya az gelişmiş ülkelere özgüdür; gelişmiş ülkelerin piramitleri dar tabanlı, dik kenarlı silindir veya arı kovanı biçimindedir (E yanlış).",
