    "professor": "Ömer Karahan",
    "question": "Tıbbi Deontoloji ve hasta hakları mevzuatına göre hekimin tıbbi sır saklama yükümlülüğü (tıbbi gizlilik) ile ilgili aşağıdaki ifadelerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Sırrın saklanmasının toplum sağlığını veya başkalarının yaşamını ağır tehlikeye sokması durumunda bildirim yapılabilir."
      },
      {
        "letter": "B",
        "text": "Mesleğin icrası sırasında hastadan öğrenilen sırlar hasta ölse dahi açıklanamaz."
      },
      {
        "letter": "C",
        "text": "Kanuni zorunluluk (bulaşıcı hastalık bildirimi, adli bildirim) hallerinde ilgili mercilere bildirim yapılır."
      },
      {
        "letter": "D",
        "text": "Hasta reşit ve temyiz kudretine sahip olsa bile hekim hastanın sırlarını anne, baba gibi birinci derece yakınlarına serbestçe açıklayabilir."
      },
      {
        "letter": "E",
        "text": "Hastanın açık yazılı rızası olduğu durumlarda sır açıklanabilir."
      }
    ],
