    "professor": "M. Haluk Uluutku",
    "question": "Anatomi terminolojisinde Latin alfabesinde yer alan \"T\" harfinin Türkçe alfabedeki \"S\" harfi sesi ile okunduğu örnek hangisidir? Seçiniz.",
