    "professor": "M. Haluk Uluutku",
    "question": "Tarihsel süreçte anatomi terimlerinin sadeleşmesi ve bir sistematiğe bağlanması için NOMİNA ANATOMİCA denilen uluslar arası toplantılar yapılmıştır. Bu toplantılardan ilki hangisidir? Seçiniz.",
