    "q_num": 75,
    "subject": "Anatomi",
    "professor": "Belirtilmemiş",
    "question": "Rastgele seçilmiş 205 doktor, branşları ve ilaç promosyonlarını etik bulup bulmamalarına göre aşağıdaki gibi sınıflandırılmıştır: Doktorların branşları ile ilaç promosyonlarını etik bulup bulmamaları arasında  = 0,05 anlam düzeyinde ilişki olup olmadığını aşağıdaki sonuçlara göre yorumlayınız.",
    "options": [
      {
        "letter": "A",
        "text": "p = 0, 517 > α = 0, 05 olduğundan H0 reddedilir. % 95 güvenle ilişki vardır."
      },
      {
        "letter": "B",
        "text": "p =0,5172> α = 0, 05 olduğundan H0 reddedilir. % 95 güvenle ilişki yoktur."
      },
      {
        "letter": "C",
        "text": "p = 0, 517 > α = 0, 05 olduğundan H0 reddedilemez. % 95 güvenle ilişki yoktur.-Doğru Seçenek"
      },
      {
        "letter": "D",
        "text": "p = 0, 394 > α = 0, 05 olduğundan H0 reddedilir. % 95 güvenle ilişki vardır."
      },
      {
        "letter": "E",
        "text": "p =0,3942> α = 0, 05 olduğundan H0 reddedilemez. % 95 güvenle ilişki yoktur."
      }
    ],
    "answer": "C",
    "open_answer": "",
    "explanation": "Ki-kare bağımsızlık testinde hesaplanan `p = 0,517` değeri anlamlılık düzeyi `α = 0,05`'ten büyük (`p = 0,517 > 0,05`) olduğu için **sıfır hipotezi (H0) reddedilemez ve %95 güvenle hekimlerin branşları ile ilaç promosyonlarını etik bulmaları arasında istatistiksel olarak anlamlı bir ilişki yoktur** (C doğru). `p = 0,517 > 0,05` iken H0 hipotezi reddedilmez; H0 reddedilemediğinde değişkenler arasında ilişki bulunduğu sonucuna varılamaz (A yanlış). H0 hipotezi reddedildiğinde istatistiksel olarak ilişki olduğu kabul edilir; ayrıca `p = 0,5172 > 0,05` durumunda H0 reddedilemez (B yanlış). Hem sorunun analizindeki anlamlılık değeri `0,394` değil `0,517`'dir hem de `p > 0,05` durumunda H0 reddedilip ilişki vardır denemez (D yanlış). Kullanılan p değeri test çıktısındaki gerçek `0,517` değerini yansıtmamaktadır (E yanlış).",
