    "explanation": "Primer alkoller aldehit ve karboksilik asitlere, sekonder alkoller ketonlara yükseltgenir; **tersiyer alkoller ise hidroksil grubunun bağlı olduğu alfa karbonunda hidrojen atomu taşımadıkları için normal koşullarda yükseltgenmezler**, karboksilik asit oluşturdukları iddiası kimyasal olarak yanlıştır.",
    "note": "",
