    "question": "I. Elektronun bulunma olasılığının yüksek olduğu bölgeye orbital denir. II. K ve L tabakasında yer alan s orbitallerinin enerjileri eşittir. III. Çekirdekten dışa doğru tabaka sayısı arttıkça, tabakalarda yer alan orbitallerin enerji düzeyleri düşer. Yukarıdaki ifadelerin hangisi doğrudur?",
