    "professor": "Hüseyin Haydar Kutlu",
    "question": "Bakterilerin konak savunma mekanizmalarından ve özellikle nötrofil/makrofaj fagositozundan korunmasında en etkili olan hücresel yüzey yapısı aşağıdakilerden hangisidir?",
