    "subject": "Halk Sağlığı",
    "professor": "Ufuk Berberoğlu",
    "question": "Sosyal hijyenin kurucusu Dr. Alfred Grotjahn'a göre bir toplumda hastalıkların halk sağlığı açısından önemini ve önceliğini belirleyen temel ölçütler arasında hangileri yer alır?\nI. Toplumda görülme sıklığının (yaygınlığının) yüksek olması\nII. Sakatlık ve iş gücü kaybına yol açması\nIII. Sosyoekonomik nedenlerle yakından ilişkili olması",
