    "question": "Aşağıdaki verilen tanımlamaya ilişkin önermelerin doğru(D) ve yanlış(Y) sıralaması hangi seçenektedir?\"SAĞLlK; yalnızca bedensel hastalık ya da sakatlıkların bulunmayışı demek olmayıp; aynı zamanda ruhsal ve toplumsal (sosyal) yönlerden de tam bir iyilik durumudur. \"Tanım, Dünya Sağlık Örgütü'ne aittir. Tanım, Türkiye'yi de bağlamaktadır.Tanım, Anayasamızda yerini bulmaktadır. Tanım, Dünya'nın ortak tanımıdır.BedenseI-ruhsaI sağlığın yanı sıra toplumsal sağlık,",
