    "question": "Dünya Sağlık Örgütü (DSÖ)'nün görevleri konusunda verilenlerin doğru(D) ve yanlış(Y) sıralaması hangi seçenektedir? 1. Sağlık personeli eğitiminin koordinasyonu ve yönlendirilmesi.2. Epidemiyolojik, istatistik amaçlı veri toplama, yayınlama.3. Aşı ve ilaçlar için uluslararası standartlar koymak.4. Araştırma yöntemlerinin standartlarını geliştirmek.5. Sağlık",
