    "professor": "Ufuk Berberoğlu",
    "question": "Halk sağlığında koruma düzeyleri ile ilgili aşağıdaki eşleştirmelerden hangisi yanlıştır?",
    "options": [
      {
        "letter": "A",
        "text": "Çocukluk çağı aşılarının yapılması -> Primer korunma"
      },
      {
        "letter": "B",
        "text": "Diyabetli hastada diyet ve egzersiz eğitimi ile komplikasyonların geciktirilmesi -> Tersiyer korunma"
      },
      {
        "letter": "C",
        "text": "Toplumda sigara kullanımını ve obezite risk faktörlerini henüz ortaya çıkmadan önleme -> Primordial korunma"
      },
      {
        "letter": "D",
        "text": "Asemptomatik bireyde kan basıncı ölçümü ile hipertansiyon taranması -> Primer korunma"
      },
      {
        "letter": "E",
        "text": "Hastayı gereksiz aşırı medikalizasyon ve invaziv tetkiklerin zararlarından koruma -> Kuaterner korunma"
      }
    ],
    "answer": "D",
    "open_answer": "",
    "explanation": "Primer koruma hastalık etkeniyle karşılaşmayı engellemektir (aşılama gibi); asemptomatik bireylerde kan basıncı ölçülerek hipertansiyon taranması ise klinik hastalık gelişmeden patolojiyi erken evrede yakalamayı amaçlayan **Sekonder (ikincil) korumadır**, primer koruma eşleştirmesi yanlıştır.",
