    "question": "Tıpta biyopsikososyal modelin klinik hekimlik uygulamalarına ve hasta bakımına sağladığı katkılar arasında aşağıdakilerden hangileri yer alır?\nI. Hastalığın yalnızca biyolojik değil psikolojik ve sosyal boyutlarını da değerlendirme\nII. Hasta-hekim iletişimini ve tedaviye uyumu güçlendirme\nIII. Hastanın stres ve baş etme mekanizmalarını destekleme",
