    "question": "AşağıdakiIerden hangisi Limbik Sistem Fonksiyonları ile ilgili yanlış olan önermedir?",
    "options": [
      {
        "letter": "A",
        "text": "Duygular beyinde karmaşık etkileşimi sahiptir ve temel anlamda limbik sistemle ilişkilidir."
      },
      {
        "letter": "B",
        "text": "Klüver-Bucy Sendromu bilateral temporal lob bozukluğu sonucunda görülen hiperseksüalite, durgunluk, çevreyi ağız yoluyla tanıma, görsel uyaranların duygusal önemini anlamada yetersizlik, hipermatemorfoz olarak dikkatin sürekli olarak kayması ile karakterize bir sendromdur."
      },
      {
        "letter": "C",
        "text": "Amigdala, anksiyete ve panik gibi öğrenilmiş korku yanıtlarına aracılık etmektedir."
      },
      {
        "letter": "D",
        "text": "Limbik sistemi içeren subkortikal yapıların uyarılması öfke yanıtlarını ortaya çıkarmaktadır."
      },
      {
        "letter": "E",
        "text": "Motivasyon, dikkat, eylemlerin sıralanması gibi yürütücü işlevlerin düzenlenmesinden temel sorumlu alandır."
      }
    ],
    "answer": "E",
    "open_answer": "",
    "explanation": "Dikkat, soyut düşünme, motivasyon ve karmaşık eylemleri planlama gibi yürütücü işlevlerin (executive functions) ana düzenleyicisi prefrontal kortekstir; **Limbik sistem ise yürütücü işlevlerden değil**, duygular, motivasyon ve belleğin afektif boyutu ile ilişkili subkortikal yapılardır.",
    "note": "",
    "q_type": "mcq",
    "incomplete": false,
    "incomplete_reason": ""
